from AlgorithmImports import *
import math


class Main(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, fillForward=False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, fillForward=False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, fillForward=False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, fillForward=False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, fillForward=False).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.order_strategies = {}

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        bars = {
            self.spy: self._get_bar(data, self.spy),
            self.aapl: self._get_bar(data, self.aapl),
            self.ibm: self._get_bar(data, self.ibm),
            self.bac: self._get_bar(data, self.bac),
            self.aig: self._get_bar(data, self.aig)
        }

        spy_bar = bars[self.spy]
        aapl_bar = bars[self.aapl]

        upward_cross = False
        downward_cross = False

        if spy_bar is not None and self.spy_sma.IsReady:
            current_sma = float(self.spy_sma.Current.Value)

            if self.previous_spy_sma is not None:
                upward_cross = (
                    self.previous_spy_sma <= current_sma
                    and spy_bar.Close > current_sma
                    and self._previous_spy_close <= self.previous_spy_sma
                )
                downward_cross = (
                    self.previous_spy_sma >= current_sma
                    and spy_bar.Close < current_sma
                    and self._previous_spy_close >= self.previous_spy_sma
                )

            self.previous_spy_sma = current_sma
            self._previous_spy_close = float(spy_bar.Close)

        if aapl_bar is not None:
            current_close = float(aapl_bar.Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif current_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = current_close

        if any(bar is None for bar in bars.values()):
            return

        if self.IsWarmingUp:
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        aapl_rsi_above_60 = float(self.aapl_rsi.Current.Value) > 60
        aapl_red_three_days = self.aapl_red_streak >= 3

        if self.strategy_a_lot > 0 and downward_cross:
            self._sell_strategy_a()

        if self.strategy_b_lot > 0 and aapl_rsi_above_60:
            self._sell_strategy_b()

        if self.strategy_a_lot == 0 and upward_cross:
            self._buy_strategy_a(float(spy_bar.Close))

        if self.strategy_b_lot == 0 and aapl_red_three_days:
            self._buy_strategy_b(float(aapl_bar.Close))

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled
        ):
            return

        strategy = self.order_strategies.get(order_event.OrderId)

        if strategy is None:
            order = self.Transactions.GetOrderById(order_event.OrderId)
            if order is not None:
                if order.Tag.startswith("STRATEGY_A"):
                    strategy = "A"
                elif order.Tag.startswith("STRATEGY_B"):
                    strategy = "B"

        if strategy == "A":
            self.strategy_a_lot = max(
                0,
                self.strategy_a_lot + int(order_event.FillQuantity)
            )
        elif strategy == "B":
            self.strategy_b_lot = max(
                0,
                self.strategy_b_lot + int(order_event.FillQuantity)
            )

    def _buy_strategy_a(self, close):
        quantity = int(
            math.floor(
                float(self.Portfolio.TotalPortfolioValue) * 0.40 / close
            )
        )

        if quantity > 0:
            ticket = self.MarketOrder(
                self.spy,
                quantity,
                tag="STRATEGY_A_BUY"
            )
            if ticket is not None:
                self.order_strategies[ticket.OrderId] = "A"

    def _sell_strategy_a(self):
        if self.strategy_a_lot > 0:
            ticket = self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="STRATEGY_A_SELL"
            )
            if ticket is not None:
                self.order_strategies[ticket.OrderId] = "A"

    def _buy_strategy_b(self, close):
        if float(self.Portfolio.Cash) < 20000:
            return

        quantity = int(math.floor(20000 / close))

        if quantity > 0:
            ticket = self.MarketOrder(
                self.aapl,
                quantity,
                tag="STRATEGY_B_BUY"
            )
            if ticket is not None:
                self.order_strategies[ticket.OrderId] = "B"

    def _sell_strategy_b(self):
        if self.strategy_b_lot > 0:
            ticket = self.MarketOrder(
                self.aapl,
                -self.strategy_b_lot,
                tag="STRATEGY_B_SELL"
            )
            if ticket is not None:
                self.order_strategies[ticket.OrderId] = "B"

    @staticmethod
    def _get_bar(data, symbol):
        if data.Bars.ContainsKey(symbol):
            return data.Bars[symbol]
        return None
